const b = $json.body || $json;
const okEstados = new Set(['nuevo', 'preparando', 'listo', 'entregado', 'cancelado']);
const ticket = String(b.ticket || '').trim();
const estado = String(b.estado || '').trim().toLowerCase();
const negocio = String(b.negocio || '').trim();
if (!ticket) return [{ json: { ok: false, error: 'falta ticket' } }];
if (!okEstados.has(estado)) return [{ json: { ok: false, error: 'estado inválido', okEstados: [...okEstados] } }];
return [{ json: {
  ok: true,
  sistema: '08-cola-pedidos-wasap',
  etapa: 'cambio_estado',
  ticket,
  negocio,
  estado,
  status: 'actualizado',
  siguiente: estado === 'listo' ? 'avisar_cliente' : null,
  todo: 'TODO: update fila Sheet + trigger 08c si listo',
  at: new Date().toISOString()
}}];
